INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,catalogue_number,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(id,7),id,
 CASE
  WHEN id LIKE 'claim.v0130.dsab_%' THEN CASE WHEN id IN ('claim.v0130.dsab_made_egypt','claim.v0130.dsab_persian_holds_egypt','claim.v0130.dsab_mentions_ahuramazda') THEN 'source.persia.dsab.achemenet' ELSE 'source.persia.dsab.vallat1974' END
  WHEN id LIKE 'claim.v0130.hieroglyphic_%' OR id LIKE 'claim.v0130.province_list_part_%' THEN 'source.iranica.epigraphy_old_persian'
  WHEN id LIKE 'claim.v0130.province_list_%' THEN 'source.iranica.susa_achaemenid'
  WHEN id='claim.v0130.subjects_no_modern_equivalence' THEN 'source.iranica.susa_achaemenid'
  ELSE 'source.iranica.susa_achaemenid' END,
 CASE
  WHEN id LIKE 'claim.v0130.dsab_%' THEN CASE WHEN id IN ('claim.v0130.dsab_made_egypt','claim.v0130.dsab_persian_holds_egypt','claim.v0130.dsab_mentions_ahuramazda') THEN 'Achemenet central part, DSab presentation and attributed translation' ELSE 'Vallat 1974, RA 68.2, pp. 157-166' END
  WHEN id LIKE 'claim.v0130.hieroglyphic_%' OR id LIKE 'claim.v0130.province_list_part_%' THEN 'Encyclopaedia Iranica, Epigraphy i, DSab paragraph'
  WHEN id LIKE 'claim.v0130.province_list_%' OR id='claim.v0130.subjects_no_modern_equivalence' THEN 'Encyclopaedia Iranica, Susa iii, statue paragraph'
  ELSE 'Encyclopaedia Iranica, Susa iii, statue paragraph' END,
 CASE WHEN id LIKE 'claim.v0130.dsab_%' THEN 'DSab' ELSE NULL END,
 CASE WHEN id LIKE 'claim.v0130.statue_%' OR id LIKE 'claim.v0130.province_list_24' THEN 'ARCHAEOLOGICAL' WHEN id='claim.v0130.subjects_no_modern_equivalence' THEN 'MODERN_SCHOLARSHIP' ELSE 'INSCRIPTION' END,
 'SUPPORTS',confidence,'Independent summary; source and section/page locator retained.'
FROM claims WHERE id LIKE 'claim.v0130.%';

INSERT OR IGNORE INTO conflicts(id,subject_id,variant_group,claim_a_id,claim_b_id,conflict_type,status,summary,resolution_notes) VALUES
('conflict.v0130.statue_origin_evidence_layers','museum.iran.darius_susa_statue','susa.darius.creation','claim.v0130.dsab_made_egypt','claim.v0130.statue_wadi_hammamat','EVIDENCE_LAYER','OPEN','The inscription states Egyptian manufacture while material analysis independently supports Egyptian stone provenance; these are converging but different evidence types.','Keep textual assertion and archaeometric interpretation separate.'),
